import sys, random
from math import sqrt

def gcd(a, b):
	while 1:
		if b == 0:
			return a
		a %= b
		if a == 0:
			return b
		b %= a

def function(L, R):
	sum = 0
	for i in range(L, R + 1):
		for j in range(1, i + 1):
			cnt = 0
			if j * (j + 1) == 2 * i:
				for k in range(1, i + 1):
					if gcd(k, i) == 1:
						cnt += 1
			sum = sum + cnt
	return sum

def eulerSieve(N):
	if N == 1:
		return [0, 1]
	limit = int(N ** 0.5) + 1
	sieve = [0] * (N + 1)
	for i in range(3, limit, 2):
		if sieve[i] == 0:
			for j in range(i * i, N + 1, 2 * i):
				sieve[j] = i
	sieve[0:3] = [0, 1, 1]
	for i in range(3, N + 1):
		p = sieve[i]
		if p != 0:
			j = i // p
			sieve[i] = sieve[j] * (p if j % p == 0 else p - 1)
		elif i & 3 == 0:
			sieve[i] = sieve[i >> 1] << 1
		elif i & 1 == 0:
			sieve[i] = sieve[i >> 1]
		else:
			sieve[i] = i - 1
	return sieve

def solve():

	def f(n):
		return int((-1 + (1 + 8 * n) ** 0.5) / 2.0)
	N = 1420000
	phis = eulerSieve(N + 1)
	phi2 = [0] * (N + 1)
	for i in range(1, N + 1):
		j = i * (i + 1)
		phi2[i] = phis[i] * phis[i + 1]
		if not j & 3:
			phi2[i] //= 2
	for j in range(1, N + 1):
		phi2[j] += phi2[j - 1]
	stdin = sys.stdin
